function loadModules(env) {
  const ctx = contextFor(env);
  // FIX-NAV-REFRESH-V1: coalesceLoad (shared/ui) é carregado antes, como em _scripts.html.
  for (const rel of ['modules/shared/ui/mutation-flow.js', ...MODULES]) { vm.runInContext(fs.readFileSync(path.join(JS_ROOT, rel), 'utf8'), ctx); }
  return ctx;
}

function runAppSlices(ctx, appSource, names) {
  const lines = appSource.split('\n');
  const slice = (n) => {
    const s = lines.findIndex((l) => l.startsWith(`function ${n}(`) || l.startsWith(`async function ${n}(`));
    if (s < 0) { throw new Error(`não achei ${n}`); }
    let e = s;
    while (!/^}/.test(lines[e])) { e++; }
    return lines.slice(s, e + 1).join('\n');
  };
  const consts = ['OUTSOURCED_COMPANY_CORPORATE_FIELDS', 'CONTRACTED_VINCULOS_FALLBACK'].map((n) => lines.find((l) => l.startsWith(`const ${n} = `)));
  if (consts.some((c) => !c)) { throw new Error('constantes de bloco não encontradas'); }
  vm.runInContext(`{ const state = globalThis.__EPI_APP_STATE__; const refs = globalThis.__EPI_REFS__;\n${consts.join('\n')}\n`
    + `${names.map(slice).join('\n')}\n${names.map((n) => `globalThis.${n} = ${n};`).join(' ')} }`, ctx);
  return ctx;
}

// FIX-COLAB-TERC-V1 replaces only the three frozen success-path defects.
for (const key of ['vinculoUnidadeLink', 'vinculoUnidadeAtivar', 'vinculoUnidadeArquivar']) {
  EXPECTED[key].refs = EXPECTED.renderColab.refs;
  EXPECTED[key].log = EXPECTED[key].log.slice(0, -1).concat([['bootstrap', { preserveView: true }]], EXPECTED.renderColab.log);
}

// I18N-FULL-V1: as opções vazias mantêm value=""; só ganham binding.
for (const expected of Object.values(EXPECTED)) {
  for (const id of ['outsourced-company-unit', 'outsourced-employee-unit']) {
    if (expected.nodes?.[id]?.[1] === '<option value="">Sem unidade operacional ativa</option>') {
      expected.nodes[id][1] = '<option value="" data-i18n="employee.noActiveOperationalUnit">Sem unidade operacional ativa</option>';
    }
  }
}

module.exports = function ({ testAsync, test, assert, eq }) {
  testAsync('UBX-V4 Terceirizados: os módulos reproduzem as funções originais', async () => {
    const actual = await scenario(loadModules);
    for (const key of Object.keys(EXPECTED)) {
      eq(JSON.stringify(actual[key]), JSON.stringify(EXPECTED[key]), key);
    }
    eq(Object.keys(actual).sort().join(','), Object.keys(EXPECTED).sort().join(','));
  });

  test('UBX-V4 Terceirizados: globais, namespaces, camadas e ordem de carga', () => {
    const ctx = loadModules(makeEnv());
    for (const name of NAMES) { eq(typeof ctx[name], 'function', name); }
    for (const ns of ['__EPI_OUTSOURCED_API__', '__EPI_OUTSOURCED_COMPANIES_UI__', '__EPI_OUTSOURCED_REQUESTS_UI__', '__EPI_OUTSOURCED_EMPLOYEES_UI__']) {
      assert(Object.isFrozen(ctx[ns]), `${ns} congelado`);
    }
    assert(!('loadEmployees' in ctx), 'nenhum loader fictício reintroduzido');
    const scripts = fs.readFileSync(path.resolve(JS_ROOT, '..', 'views', '_scripts.html'), 'utf8');
    const order = [...scripts.matchAll(/<script[^>]+src="([^"?]+)/g)].map((m) => m[1]);
    const idx = MODULES.map((m) => order.indexOf(`/js/${m}`));
    assert(idx.every((i) => i >= 0) && idx[0] < idx[1], 'integração antes das UIs');
    assert(Math.max(...idx) < order.indexOf('/app.js'), 'antes do app.js');
    assert(order.indexOf('/js/modules/api-client.js') < idx[0], 'api-client antes da integração');
    const app = fs.readFileSync(path.resolve(JS_ROOT, '..', 'app.js'), 'utf8');
    for (const name of NAMES) {
      assert(!new RegExp(`^(?:async\\s+)?function\\s+${name}\\(`, 'm').test(app), `${name} voltou ao app.js`);
    }
    // UBX-V5 Etapa 1: com archiveEntityRecord global (modules/archival/ui), o atalho mora no módulo.
    eq(typeof ctx.archiveOutsourcedEmployee, 'function', 'archiveOutsourcedEmployee publicado pelo módulo');
    assert(!/^async function archiveOutsourcedEmployee\(/m.test(app), 'archiveOutsourcedEmployee saiu do app.js');
    assert(!/^const (OUTSOURCED_COMPANY_CORPORATE_FIELDS|CONTRACTED_VINCULOS_FALLBACK)/m.test(app), 'constantes saíram do app.js');
  });
};

module.exports.scenario = scenario;
module.exports.contextFor = contextFor;
module.exports.runAppSlices = runAppSlices;
